import AppKit
import Sparkle

enum UpdateReleaseNotes {
    static let historyURL = URL(string: "https://github.com/Qrivi/CodexMeter/releases")!

    static func relevantNotes(_ notes: NSAttributedString, installedVersion: String) -> NSAttributedString {
        // These headings are generated by generate-update-notes.py. Work on the
        // rendered text so Sparkle's fonts, lists, emphasis, and links stay intact.
        let heading = try! NSRegularExpression(pattern: #"(?m)^Version ([0-9]+\.[0-9]+\.[0-9]+)[\t ]*$"#)
        let text = notes.string as NSString
        let matches = heading.matches(in: notes.string, range: NSRange(location: 0, length: text.length))
        guard !matches.isEmpty else { return notes }

        var footerRange: NSRange?
        notes.enumerateAttribute(.link, in: NSRange(location: 0, length: notes.length)) { value, range, _ in
            if (value as? URL) == historyURL || (value as? String) == historyURL.absoluteString {
                footerRange = range
            }
        }
        let contentEnd = footerRange?.location ?? notes.length
        let result = NSMutableAttributedString(string: "")
        let comparator = SUStandardVersionComparator()
        for (index, match) in matches.enumerated() {
            let version = text.substring(with: match.range(at: 1))
            guard comparator.compareVersion(version, toVersion: installedVersion) == .orderedDescending else { continue }
            let end = index + 1 < matches.count ? matches[index + 1].range.location : contentEnd
            result.append(notes.attributedSubstring(from: NSRange(location: match.range.location, length: end - match.range.location)))
        }
        if let footerRange {
            if result.length > 0, !result.string.hasSuffix("\n") {
                result.append(NSAttributedString(string: "\n"))
            }
            result.append(notes.attributedSubstring(from: NSRange(location: footerRange.location, length: notes.length - footerRange.location)))
        }
        return result
    }
}
